  if (!["a", "button", "input"].includes(el.tagName.toLowerCase())) {
    el.setAttribute("tabindex", "0");
    el.setAttribute("role", "button");
    el.addEventListener("keydown", (e) => {
      if (e.key === "Enter" || e.key === " ") {
        el.click();
        e.preventDefault();
      }
    });
  }
});
